import math

def calc(items, x):
    """
    Computes a value from given items at a point.
    return items[0] + items[1] * x + items[2] * x^2 + .... items[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(items)])

def find_zero(items, tol=1e-12, max_iter=1000):
    """
    Finds a single root of the polynomial with given coefficients `items`.
    Coefficients are in ascending order of power:
        f(x) = items[0] + items[1]*x + items[2]*x^2 + ... + items[n]*x^n

    The function uses Newton-Raphson method with a fallback to bisection.

    Returns a floating point root approximation.

    Raises ValueError if no root is found or input is invalid.
    """
    if not items:
        raise ValueError("Coefficient list must not be empty.")

    # Remove trailing zeros (highest powers with zero coeff)
    while len(items) > 1 and abs(items[-1]) < 1e-15:
        items = items[:-1]
    degree = len(items) - 1

    if degree < 1:
        # Constant polynomial, no root unless zero
        if abs(items[0]) < tol:
            return 0.0
        else:
            raise ValueError("No roots for constant non-zero polynomial.")

    # Derivative coefficients for Newton-Raphson
    deriv = [i * items[i] for i in range(1, len(items))]

    def f(x):
        return calc(items, x)
    def fprime(x):
        return calc(deriv, x)

    # To use bisection fallback, we try to find an interval [a,b]
    # where f(a)*f(b) < 0.
    # Start searching intervals exponentially outward from 0.
    def find_bracket():
        a, b = 0.0, 1.0
        fa, fb = f(a), f(b)
        for _ in range(50):
            if fa == 0.0:
                return (a, a)
            if fb == 0.0:
                return (b, b)
            if fa * fb < 0:
                return (a, b)
            a, b = b, b * 2
            fa, fb = fb, f(b)
        # If no bracket found, try negative side similarly
        a, b = 0.0, -1.0
        fa, fb = f(a), f(b)
        for _ in range(50):
            if fa == 0.0:
                return (a, a)
            if fb == 0.0:
                return (b, b)
            if fa * fb < 0:
                return (a, b)
            a, b = b, b * 2
            fa, fb = fb, f(b)
        return None

    bracket = find_bracket()
    if bracket is None:
        # No sign change found, try Newton from x=0
        x = 0.0
        for _ in range(max_iter):
            fx = f(x)
            if abs(fx) < tol:
                return x
            fpx = fprime(x)
            if abs(fpx) < 1e-14:
                break  # derivative too small, abort
            x_new = x - fx/fpx
            if abs(x_new - x) < tol:
                return x_new
            x = x_new
        raise ValueError("Root not found: no sign bracket and Newton failed.")

    a, b = bracket
    fa, fb = f(a), f(b)
    if a == b:
        # root found exactly
        return a

    # Bisection method on [a,b]
    for _ in range(max_iter):
        c = (a + b) / 2
        fc = f(c)
        if abs(fc) < tol or (b - a)/2 < tol:
            return c
        if fa * fc < 0:
            b, fb = c, fc
        else:
            a, fa = c, fc
    # If still no convergence, return midpoint as best guess
    return (a + b) / 2

