def tally(inp):
    """
    Given some input text made of space-separated tokens, produce a mapping of the symbol(s)
    that appear most frequently along with their counts. If multiple items share the top
    frequency, include all of them.

    Tokens are case-sensitive.

    Examples:
    tally('a b c') == {'a': 1, 'b': 1, 'c': 1}
    tally('a b b a') == {'a': 2, 'b': 2}
    tally('a b c a b') == {'a': 2, 'b': 2}
    tally('b b b b a') == {'b': 4}
    tally('') == {}
    """
    if not inp:
        return {}

    tokens = inp.split()
    counts = {}
    for token in tokens:
        counts[token] = counts.get(token, 0) + 1

    max_count = max(counts.values()) if counts else 0

    return {token: count for token, count in counts.items() if count == max_count}

def sort_array(vals):
    """
    Arrange numbers by the count of ones in their binary representation,
    using 32-bit two's complement for negative numbers.
    If counts are equal, sort by numeric value.
    """
    def count_ones_32bit(n):
        # For negative numbers, get 32-bit two's complement representation
        if n < 0:
            n = n & 0xFFFFFFFF
        return bin(n).count('1')

    return sorted(vals, key=lambda x: (count_ones_32bit(x), x))


