def collect_pieces(content):
    '''
    Given some text-like input, return a sequence of chunks obtained by dividing on gaps (any whitespace).
    If no whitespace characters appear in the content, fall back to dividing on commas ','.
    If neither form of separator is present, return the count of lower-case letters that occur at odd positions 
    in the alphabet ordering, where ord('a') = 0, ord('b') = 1, ..., ord('z') = 25.

    Examples:
    collect_pieces("Hello world!") ➞ ["Hello", "world!"]
    collect_pieces("Hello,world!") ➞ ["Hello", "world!"]
    collect_pieces("abcdef") == 3
    '''
    # Check for any whitespace character
    if any(c.isspace() for c in content):
        # split on any whitespace (one or more) using str.split()
        return content.split()
    # Else check for commas
    elif ',' in content:
        return content.split(',')
    else:
        # No whitespace or commas, count lower-case letters at odd alphabet positions
        count = 0
        for c in content:
            if 'a' <= c <= 'z':
                pos = ord(c) - ord('a')
                if pos % 2 == 1:
                    count += 1
        return count

def compare_one(p, q):
    """
    Compare two inputs (numeric or string representations of numbers with '.' or ',' decimal separators).
    Return the one that appears larger, in the original format it was given.
    Return None if they are numerically equal.
    """
    def to_float(x):
        if isinstance(x, (int, float)):
            return float(x)
        if isinstance(x, str):
            # Replace comma decimal separator with dot for conversion
            s = x.replace(',', '.')
            try:
                return float(s)
            except ValueError:
                raise ValueError(f"Cannot convert '{x}' to float")
        raise TypeError(f"Unsupported type: {type(x)}")

    val_p = to_float(p)
    val_q = to_float(q)

    if val_p == val_q:
        return None
    elif val_p > val_q:
        return p
    else:
        return q


