def prime_fib(n):
    """
    Returns the nth prime Fibonacci number, where the Fibonacci sequence starts with F1=1, F2=1.

    The Fibonacci sequence is:
    F1 = 1, F2 = 1, and for k > 2, Fk = F_{k-1} + F_{k-2}

    Among these Fibonacci numbers, we select those that are prime numbers.
    This function returns the nth such prime Fibonacci number.

    Example:
    prime_fib(1) == 2  (since Fibonacci sequence: 1,1,2,... and 2 is the first prime Fibonacci)
    prime_fib(2) == 3
    prime_fib(3) == 5
    prime_fib(4) == 13
    prime_fib(5) == 89
    prime_fib(6) == 233
    """
    if n < 1:
        raise ValueError("n must be a positive integer.")

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
